<?php require __DIR__.'/../bootstrap/app.php';if(user())go('dashboard.php');$err='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!throttle('login',8,900))$err='Too many attempts. Please wait 15 minutes.';elseif(Auth::signIn((string)($_POST['email']??''),(string)($_POST['password']??'')))go('dashboard.php');else $err='Login failed or account inactive.';}$title='Login';require __DIR__.'/../app/Views/header.php';?><section class="section"><div class="container" style="max-width:550px"><form class="formbox" method="post"><h1>Sign in</h1><?php if($err):?><div class="alert alert-danger"><?=e($err)?></div><?php endif;?><?=csrf_field()?><label class="form-label">Email</label><input class="form-control mb-3" name="email" type="email" required><label class="form-label">Password</label><input class="form-control mb-3" name="password" type="password" required><button class="btn gold">Login</button></form></div></section><?php require __DIR__.'/../app/Views/footer.php';?>